// Typed guest API. Responses are checked against the strict zod schemas in ./schema before use.
// ./types.ts is generated by `pnpm gen:api` and so far holds only /healthz; regenerate in Task 8.4 once the guest routes exist.
import type { z } from "zod";
import type { RequestOptions, Transport } from "../transport";
import type { Action } from "../ui/types";
import {
  actionResponse,
  command,
  configResponse,
  dashboardResponse,
  meResponse,
  sessionResponse,
  wsTicketResponse,
} from "./schema";

export function apiClient(transport: Transport) {
  const call = async <S extends z.ZodType>(schema: S, path: string, options?: RequestOptions): Promise<z.infer<S>> =>
    schema.parse(await transport.request(path, options));
  return {
    config: () => call(configResponse, "/api/v1/public/config"),
    // shortcut: browser redeem only; the native client (Plan 3) sends "native" and gets tokens instead of a cookie.
    redeem: (inviteSecret: string, deviceLabel?: string) =>
      call(sessionResponse, "/api/v1/auth/redeem", {
        method: "POST",
        body: { invite_secret: inviteSecret, device_label: deviceLabel, client: "browser" },
      }),
    me: () => call(meResponse, "/api/v1/me"),
    logout: async (): Promise<void> => {
      await transport.request("/api/v1/auth/logout", { method: "POST" });
    },
    wsTicket: () => call(wsTicketResponse, "/api/v1/ws-ticket", { method: "POST" }),
    renew: () => call(sessionResponse, "/api/v1/auth/session/renew", { method: "POST" }),
    dashboard: () => call(dashboardResponse, "/api/v1/dashboard"),
    /** One click is one key: a retry with the same key never runs the action twice. */
    actions: (resourceId: string, action: Action, params: Record<string, string | number>, idempotencyKey: string) =>
      call(actionResponse, "/api/v1/actions", {
        method: "POST",
        body: { resource_id: resourceId, action, params },
        idempotencyKey,
      }),
    command: (id: string) => call(command, `/api/v1/commands/${encodeURIComponent(id)}`),
  };
}

export type ApiClient = ReturnType<typeof apiClient>;
